const fallbackGuideKeys = Object.keys(pageGuides.en);

export function getCoreTranslations(language) {
  const core = localized[language] || localized.en;
  const names = languageNames[language] || languageNames.en;
  const guides = Object.fromEntries(
    fallbackGuideKeys.map((key) => {
      const titlePair = guideTitles[language]?.[key] || guideTitles.en[key] || [localized.en.nav[key] || key, localized.en.nav[key] || key];
      return [
        key,
        {
          label: titlePair[0],
          title: titlePair[1],
          steps: pageGuides[language]?.[key] || pageGuides.en[key],
        },
      ];
    })
  );

  return {
    ...core,
    languageNames: names,
    walkthrough: guides,
  };
}
